//  Do not hand-edit: `npm run build` overwrites this file and CI fails if it has
//  drifted. The scaffolding below the token list is hand-written and lives in
//  templates/QuickFiColor.swift.tmpl.
//
//  Two layers. brandGreen and brandCharcoal are PRIMITIVES: never bind a
//  component to them. Everything else is semantic — that is what components use.
//
//  Buttons are named by appearance, not rank: filled, outline, text. Ranked
//  names collided with the text emphasis ladder.
//
//  Brand green #25AB3A, oklch hue 145. Neutrals anchored on #3A3A3C, hue 286.
//  Dark background #242424, surface #2C3036 — mid-grey elevated, not near-black.
//
import SwiftUI
import UIKit

extension UIColor {
    convenience init(hex: UInt32) {
        self.init(red:   CGFloat((hex >> 16) & 0xFF) / 255.0,
                  green: CGFloat((hex >>  8) & 0xFF) / 255.0,
                  blue:  CGFloat( hex        & 0xFF) / 255.0, alpha: 1.0)
    }
    /// A dynamic colour that resolves per trait collection, so UIKit views
    /// switch mode with the system the same way the SwiftUI Color does.
    static func qf(_ light: UInt32, _ dark: UInt32) -> UIColor {
        UIColor { $0.userInterfaceStyle == .dark ? UIColor(hex: dark) : UIColor(hex: light) }
    }
}
extension Color {
    init(hex: UInt32) { self.init(UIColor(hex: hex)) }
    static func qf(_ light: UInt32, _ dark: UInt32) -> Color { Color(UIColor.qf(light, dark)) }
}

public enum QuickFiColor {

    // MARK: - Brand
    /// PRIMITIVE.
    /// The brand colour, for marks, illustration and marketing artwork.
    /// Never bind a component to this directly. It doubles as QuickFi's own seed for the runtime brand engine (tokens/brand-engine.md) — the credit-line accent and container tokens derive from a seed exactly like this one, per partner.
    public static let brandGreen = Color.qf(0x25AB3A, 0x25AB3A)
    /// PRIMITIVE.
    /// The neutral anchor; the grey ramp derives from its hue.
    /// Never bind a component to this.
    public static let brandCharcoal = Color.qf(0x3A3A3C, 0x3A3A3C)

    // MARK: - Container
    /// Every screen background.
    /// Always tinted so surface layers read by fill.
    /// Section headers only.
    public static let background = Color.qf(0xF1F1F4, 0x242424)
    /// Where all content lives: cards, sheets, list rows, dialogs, nav bars, tables.
    /// Also the fill of an OUTLINE button.
    /// In light mode this is pure white — the lightness ceiling — which is why surface-1 and surface-2 above it step BACK DOWN rather than up.
    public static let surface = Color.qf(0xFFFFFF, 0x2C3036)
    /// One elevation step above surface — content sitting on top of an already-raised layer: a tab bar or nav bar over a list of raised rows.
    /// Derived to clear a 1.10 separation floor against both surface and background, so it reads as distinct from either even if the intermediate layer isn't present.
    /// text/tertiary is NOT rated on this fill — surface's white leaves it no headroom; it lands around 4.0–4.2:1, just under the 4.5:1 floor. Use text/primary or text/secondary.
    public static let surface1 = Color.qf(0xE3E3E8, 0x393834)
    /// One elevation step above surface-1 — for content that needs to read as more prominent still. Rare; most screens never need it.
    /// Derived the same way as surface-1: clears 1.10 separation against surface-1, surface AND background.
    /// text/tertiary is NOT rated on this fill either — it lands around 3.5–3.7:1 in both modes, below the 4.5:1 text floor. Use text/primary or text/secondary here.
    public static let surface2 = Color.qf(0xD6D6DB, 0x41403C)
    /// Recessed areas INSIDE a surface: inputs, wells, disabled fields. Structural only — it does not carry a pressed or selected state; that is action/selected's job.
    /// Carries the same faint per-credit-line tint as every container token (tokens/brand-engine.md).
    /// Takes textPrimary only — textLink is measurably below the text floor on it, in every registered and synthetic credit line, and is not rated for this fill.
    /// DARKER than its parent in light, LIGHTER in dark.
    public static let subsurface = Color.qf(0xD8D8DB, 0x3C3C44)
    /// The page wash's corner tone. BRAND-DERIVED and DARK-MODE ONLY — this static value is container/background itself, so an unbranded page is flat, and so is every light page. See tokens/brand-engine.md, 'The page wash'.
    /// Never set this by hand and never paint a page gradient by hand: two radial glows (top-left and bottom-right, radius 120% of the page so they meet in the middle, haze ring at 75%, faded out at 100%) are the engine's contract, and the derived corner holds the page's OWN lightness so text stays legible on it.
    public static let backgroundWash = Color.qf(0xF1F1F4, 0x242424)
    /// The page wash's haze ring — black at 60% pre-composited over the page, so every stop of each glow is OPAQUE and renders identically on CSS, SwiftUI and Compose. BRAND-DERIVED and DARK-MODE ONLY; this static value is container/background itself.
    /// It is deliberately DARKER than container/background once derived, which for any other token would read as a hole. A hole looks recessed FROM the page; this is part of the page, and it moves every obligation the safe way — light text gains contrast, cards gain separation.
    public static let backgroundWashHaze = Color.qf(0xF1F1F4, 0x242424)

