    /// Info: text sitting on the tint.
    public static let infoText = Color.qf(0x0867B1, 0x87C2FE)
    /// Info: the tint itself.
    public static let infoBg = Color.qf(0xE3F4FF, 0x293C50)
    /// Notify: icon glyphs, solid fills, 2px borders.
    /// Its solid also serves as an action fill — buttons bind to action/filled/notify, which carries the same base value.
    public static let notify = Color.qf(0x8B37C3, 0xA96CD3)
    /// Notify: text sitting on the tint.
    public static let notifyText = Color.qf(0x8548AC, 0xD9A7FE)
    /// Notify: the tint itself.
    public static let notifyBg = Color.qf(0xFBEAFF, 0x433250)
    /// The count badge: unread counts, cart totals, alert tallies.
    /// A solid fill whose numeral is textOnBadge. Not a status — no -text or -bg role.
    /// Never use feedback/error as a badge fill; it is a graphics red at 3.4:1.
    public static let badge = Color.qf(0xC8102E, 0xFF8983)

    // MARK: - Elevation
    /// The colour every shadow on every platform draws from. Never a fill, never a stroke, never text.
    /// Near-black in light and PURE black in dark. Dark needs the extra depth because a shadow there has to darken container/background #242424 rather than a near-white page — the same near-black used in light is barely distinguishable from the surface it falls on.
